import{_ as o}from"./chunks/第一步-03.BbZWR5tM.js";import{_ as a}from"./chunks/管理后台.DGJthuhP.js";import{_ as r,o as t,c as i,a2 as p}from"./chunks/framework.CqGPl1zp.js";const d="/newx-doc/img/%E5%B7%A5%E4%BD%9C%E6%B5%81%E6%89%8B%E5%86%8C/%E5%8A%9F%E8%83%BD%E5%BC%80%E5%90%AF/%E7%AC%AC%E4%B8%80%E6%AD%A5-01.png",l="/newx-doc/img/%E5%B7%A5%E4%BD%9C%E6%B5%81%E6%89%8B%E5%86%8C/%E5%8A%9F%E8%83%BD%E5%BC%80%E5%90%AF/%E7%AC%AC%E4%B8%80%E6%AD%A5-02.png",c="/newx-doc/img/%E5%B7%A5%E4%BD%9C%E6%B5%81%E6%89%8B%E5%86%8C/%E5%8A%9F%E8%83%BD%E5%BC%80%E5%90%AF/SQL%E5%AF%BC%E5%85%A5.png",m="/newx-doc/img/%E5%B7%A5%E4%BD%9C%E6%B5%81%E6%89%8B%E5%86%8C/%E5%8A%9F%E8%83%BD%E5%BC%80%E5%90%AF/Activiti.png",v=JSON.parse('{"title":"功能开启","description":"","frontmatter":{},"headers":[],"relativePath":"bpm.md","filePath":"bpm.md","lastUpdated":null}'),n={name:"bpm.md"};function s(u,e,b,h,_,g){return t(),i("div",null,[...e[0]||(e[0]=[p('<h1 id="功能开启" tabindex="-1">功能开启 <a class="header-anchor" href="#功能开启" aria-label="Permalink to &quot;功能开启&quot;">​</a></h1><p>进度说明：</p><ul><li>管理后台，请使用 <a href="https://gitee.com/yudaocode/yudao-ui-admin-vue3" target="_blank" rel="noreferrer">https://gitee.com/yudaocode/yudao-ui-admin-vue3</a> 仓库的 <code>master</code> 分支</li><li>后端项目，请使用 <a href="https://gitee.com/zhijiantianya/ruoyi-vue-pro" target="_blank" rel="noreferrer">https://gitee.com/zhijiantianya/ruoyi-vue-pro</a> 仓库的 <code>master</code>（JDK8）、<code>master-jdk17</code>（JDK17/21）或 <code>master-jdk25</code>（JDK25）分支</li></ul><p>BPM 系统，后端由 <code>yudao-module-bpm</code> 模块实现，前端由 <code>yudao-ui-admin-vue3</code> 的 <code>bpm</code> 目录实现。</p><p>考虑到编译速度，默认 <code>yudao-module-bpm</code> 模块是关闭的，需要手动开启。步骤如下：</p><ul><li>第一步，开启 <code>yudao-module-bpm</code> 模块</li><li>第二步，导入 bpm 系统的 SQL 数据库脚本</li><li>第三步，重启后端项目，确认功能是否生效</li></ul><h2 id="_1-第一步-开启模块" tabindex="-1">1. 第一步，开启模块 <a class="header-anchor" href="#_1-第一步-开启模块" aria-label="Permalink to &quot;1. 第一步，开启模块&quot;">​</a></h2><p>① 修改根目录的 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/pom.xml" target="_blank" rel="noreferrer"><code>pom.xml</code></a> 文件，取消 <code>yudao-module-bpm</code> 模块的注释。</p><p><img src="'+d+'" alt="引入  模块"></p><p>② 第二步，修改 <code>yudao-server</code> 的 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-server/pom.xml" target="_blank" rel="noreferrer"><code>pom.xml</code></a> 文件，取消 <code>yudao-module-bpm</code> 依赖的注释，并进行 IDEA 的 Maven 刷新。</p><p><img src="'+l+'" alt="引入  依赖"></p><p>③ 点击 IDEA 右上角的【Reload All Maven Projects】，刷新 Maven 依赖。如下图所示：</p><p><img src="'+o+'" alt="刷新 Maven 依赖"></p><h2 id="_2-第二步-导入-sql" tabindex="-1">2. 第二步，导入 SQL <a class="header-anchor" href="#_2-第二步-导入-sql" aria-label="Permalink to &quot;2. 第二步，导入 SQL&quot;">​</a></h2><p>点击 <a href="https://lwb8832652.github.io/newx-doc/sql/bpm.sql" target="_blank" rel="noreferrer">下载 SQL</a> 直接下载 SQL 文件，导入到数据库中。</p><p>友情提示：↑↑↑ bpm.sql 是可以点击下载的！ ↑↑↑</p><p>重要说明：该 SQL 仅芋道星球成员可使用和商用，否则视为侵权（索赔 100 万，永久追溯）【下载即视为同意】。</p><p><img src="'+c+'" alt="导入 "></p><p>以 <code>bpm_</code> 作为前缀的表，就是 BPM 模块的表。</p><h2 id="_3-第三步-重启项目" tabindex="-1">3. 第三步，重启项目 <a class="header-anchor" href="#_3-第三步-重启项目" aria-label="Permalink to &quot;3. 第三步，重启项目&quot;">​</a></h2><p>重启后端项目，重启项目，看到 <code>Property Source flowable-liquibase-override refreshed</code> 说明开启成功。</p><p>然后访问前端的 BPM 菜单，确认功能是否生效。如下图所示：</p><p><img src="'+a+'" alt="管理后台"></p><p>另外，启动过程中，Flowable 会自动创建 <code>ACT_</code> 和 <code>FLW_</code> 开头的表。</p><p>常见问题：</p><p>① 问题：为什么在 [流程管理 -&gt; 流程模型] 菜单里，看不到流程模型？</p><p>因为 Flowable 是自己创建 <code>ACT_</code> 和 <code>FLW_</code> 开头的表，所以我只暂时导出 <code>bpm_</code> 开头的表结构给大家，具体的数据不太还弄。</p><p>你可以参考 <a href="./bpm/use-bpm-form">《审批接入（流程表单）》</a> 文档，自己创建一个流程模型，不会很复杂哈。</p><p>② 问题：如果启动中报 <a href="https://gitee.com/zhijiantianya/ruoyi-vue-pro/issues/I57FYM" target="_blank" rel="noreferrer">MySQL “Specified key was too long; max key length is 1000 bytes”</a> 错误？</p><p>解决方案：可以将 MySQL 的缺省存储引擎设置为 innodb，即 <code>default-storage-engine=innodb</code> 配置项。</p><p>③ 问题：如果 Flowable 启动报错 <code>problem during schema upgrade&amp;&amp;couldn‘t upgrade db schema</code> 错误？</p><p>解决方案：参见 <a href="https://www.cnblogs.com/sowler/p/17195427.html" target="_blank" rel="noreferrer">https://www.cnblogs.com/sowler/p/17195427.html</a> 帖子，MySQL 不区分大小写导致的，需要调整为区分。</p><p>④ 问题：我想使用达梦数据库，怎么办？</p><p>解决方案：参见 <a href="./bpm/dameng">《工作流（达梦适配）》</a> 文档。</p><h2 id="_666-后续学习" tabindex="-1">666. 后续学习 <a class="header-anchor" href="#_666-后续学习" aria-label="Permalink to &quot;666. 后续学习&quot;">​</a></h2><p>建议阅读如下两篇文档，对整个工作流建立一个整体的认识：</p><ul><li><a href="./bpm/use-bpm-form">《审批接入（流程表单）》</a></li><li><a href="./bpm/use-business-form">《审批接入（业务表单）》</a></li></ul><h2 id="可忽略-补充说明-如何集成-activiti" tabindex="-1">（可忽略）补充说明：如何集成 Activiti？ <a class="header-anchor" href="#可忽略-补充说明-如何集成-activiti" aria-label="Permalink to &quot;（可忽略）补充说明：如何集成 Activiti？&quot;">​</a></h2><p>Activiti 和 Flowable 提供的 Java API 是基本一致的，例如说 Flowable 的 <code>org.flowable.engine.RepositoryService</code> 对应 Activiti 的 <code>org.activiti.engine .RepositoryService</code>。所以，我们可以修改 <code>import</code> 的包路径来替换。</p><p>另外，在项目的老版本，我们也提供了 Activiti 实现，你可以具体参考下：</p><ul><li><a href="https://gitee.com/zhijiantianya/ruoyi-vue-pro/tree/v1.6.2/yudao-framework/yudao-spring-boot-starter-activiti" target="_blank" rel="noreferrer"><code>yudao-spring-boot-starter-activiti</code></a></li><li><a href="https://gitee.com/zhijiantianya/ruoyi-vue-pro/tree/v1.6.2/yudao-module-bpm/yudao-module-bpm-biz-activiti" target="_blank" rel="noreferrer"><code>yudao-module-bpm-biz-activiti</code></a></li></ul><p><img src="'+m+'" alt="项目结构"></p>',42)])])}const A=r(n,[["render",s]]);export{v as __pageData,A as default};
